qa.query:
BEGIN TRANSACTION READ ONLY;
WITH qa AS (SELECT c.slug,q.check_type,q.status,q.details, EXISTS(SELECT 1 FROM public.platform_admins p WHERE p.user_id=q.checked_by AND p.active AND p.role IN ('owner','admin','reviewer')) AS active_review_role FROM public.calculator_qa_checks q JOIN public.calculator_catalog_admin c ON c.id=q.calculator_id), src AS (SELECT c.slug,EXISTS(SELECT 1 FROM public.platform_admins p WHERE p.user_id=s.reviewed_by AND p.active AND p.role IN ('owner','admin','reviewer')) AS active_review_role FROM public.calculator_source_evidence s JOIN public.calculator_catalog_admin c ON c.id=s.calculator_id)
SELECT jsonb_build_object('observed_at',now(),
'qa_aggregate',(SELECT jsonb_agg(t) FROM(SELECT CASE WHEN slug IN ('percentage-increase-calculator','percentage-decrease-calculator','square-calculator','cube-calculator','square-root-calculator','cube-root-calculator','reciprocal-calculator','hypotenuse-calculator','triangle-area-calculator','rectangle-area-calculator','rectangle-perimeter-calculator','square-area-calculator','square-perimeter-calculator','circle-diameter-calculator','parallelogram-area-calculator','trapezoid-area-calculator','rectangular-prism-volume-calculator','pythagorean-theorem-calculator','degrees-to-radians-calculator','radians-to-degrees-calculator','percentage-change-calculator','ratio-calculator','proportion-calculator','fraction-calculator','fraction-to-decimal-calculator','average-two-numbers-calculator','gcf-calculator','factor-calculator','circle-area-calculator','circle-circumference-calculator','sphere-volume-calculator','sphere-surface-area-calculator','cylinder-volume-calculator','cone-volume-calculator','exponent-calculator','logarithm-calculator','remainder-calculator','lcm-calculator','scientific-notation-calculator','percent-error-calculator','rounding-calculator','weighted-average-two-values-calculator','decimal-to-fraction-calculator','polygon-area-calculator') THEN 'candidate44' ELSE 'other165' END AS cohort,status,count(*) AS count,count(*) FILTER(WHERE length(trim(coalesce(details,'')))>0) AS nonempty_details,count(*) FILTER(WHERE details ~* 'https?://') AS details_with_http_url,count(*) FILTER(WHERE active_review_role) AS active_review_role_count FROM qa GROUP BY 1,status ORDER BY 1,status)t),
'qa_patterns',(SELECT jsonb_agg(t) FROM(SELECT check_type,status,details,count(*) AS count FROM qa GROUP BY check_type,status,details ORDER BY check_type,status,details LIMIT 100)t),
'source_role_aggregate',(SELECT jsonb_agg(t) FROM(SELECT CASE WHEN slug IN ('percentage-increase-calculator','percentage-decrease-calculator','square-calculator','cube-calculator','square-root-calculator','cube-root-calculator','reciprocal-calculator','hypotenuse-calculator','triangle-area-calculator','rectangle-area-calculator','rectangle-perimeter-calculator','square-area-calculator','square-perimeter-calculator','circle-diameter-calculator','parallelogram-area-calculator','trapezoid-area-calculator','rectangular-prism-volume-calculator','pythagorean-theorem-calculator','degrees-to-radians-calculator','radians-to-degrees-calculator','percentage-change-calculator','ratio-calculator','proportion-calculator','fraction-calculator','fraction-to-decimal-calculator','average-two-numbers-calculator','gcf-calculator','factor-calculator','circle-area-calculator','circle-circumference-calculator','sphere-volume-calculator','sphere-surface-area-calculator','cylinder-volume-calculator','cone-volume-calculator','exponent-calculator','logarithm-calculator','remainder-calculator','lcm-calculator','scientific-notation-calculator','percent-error-calculator','rounding-calculator','weighted-average-two-values-calculator','decimal-to-fraction-calculator','polygon-area-calculator') THEN 'candidate44' ELSE 'other165' END AS cohort,count(*) AS count,count(*) FILTER(WHERE active_review_role) AS active_review_role_count FROM src GROUP BY 1 ORDER BY 1)t),
'bounded_samples',(SELECT jsonb_agg(t) FROM(SELECT * FROM qa WHERE slug IN ('percentage-of-value-calculator','square-calculator','percentage-increase-calculator') ORDER BY slug,check_type)t)
) AS evidence; COMMIT;
